INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Lernfeld 1 > IT-Arbeitsplätze im Kontext > Entwicklungsgeschichte & Trends Computertechnik
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Hat die Entwicklung der Computertechnik die Arbeitsweise an IT-Arbeitsplätzen verändert?', 2, '[{"text": "Ja", "correct": true, "because": "Technologische Fortschritte haben Arbeitsprozesse automatisiert und effizienter gemacht"}, {"text": "Nein", "correct": false, "because": "Entwicklung beeinflusst Arbeitsweise"}]'),
('00000000-0000-0000-0000-000000000000', 'Waren die ersten Computer ursprünglich für den privaten Gebrauch entwickelt?', 2, '[{"text": "Nein", "correct": true, "because": "Sie wurden für wissenschaftliche und militärische Zwecke gebaut"}, {"text": "Ja", "correct": false, "because": "Nicht primär für Privatnutzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Miniaturisierung ein aktueller Trend in der Computertechnik?', 2, '[{"text": "Ja", "correct": true, "because": "Kleinere, leistungsfähigere Geräte sind gefragt"}, {"text": "Nein", "correct": false, "because": "Miniaturisierung ist Trend"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Trends in der Computertechnik die Anforderungen an IT-Arbeitsplätze beeinflussen?', 2, '[{"text": "Ja", "correct": true, "because": "Neue Technologien ändern Arbeitsanforderungen"}, {"text": "Nein", "correct": false, "because": "Trends wirken sich aus"}]'),
('00000000-0000-0000-0000-000000000000', 'War die Einführung des Internets ein unwichtiger Schritt in der Computertechnik?', 2, '[{"text": "Nein", "correct": true, "because": "Revolutionierte Kommunikation und Datenzugriff"}, {"text": "Ja", "correct": false, "because": "Internet war entscheidend"}]'),
-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Entwicklung markierte den Übergang zu persönlichen Computern?', 3, '[{"text": "Einführung des Mikroprozessors", "correct": true, "because": "Ermöglichte kleinere, erschwingliche Geräte"}, {"text": "Erfindung des Transistors", "correct": false, "because": "Früherer Schritt"}, {"text": "Entwicklung des Internets", "correct": false, "because": "Späterer Schritt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Trend prägt aktuell die Computertechnik?', 2, '[{"text": "Cloud Computing", "correct": true, "because": "Dezentralisierte Datenverarbeitung"}, {"text": "Röhrencomputer", "correct": false, "because": "Veraltete Technik"}, {"text": "Manuelle Rechenmaschinen", "correct": false, "because": "Historisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Gerät gilt als einer der ersten Computer?', 2, '[{"text": "ENIAC", "correct": true, "because": "Elektronischer Rechner von 1945"}, {"text": "Abakus", "correct": false, "because": "Mechanisches Hilfsmittel"}, {"text": "Smartphone", "correct": false, "because": "Moderne Technik"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Innovation führte zur schnelleren Datenverarbeitung?', 3, '[{"text": "Transistor", "correct": true, "because": "Ersetzte Röhren und erhöhte Geschwindigkeit"}, {"text": "Papierstreifen", "correct": false, "because": "Frühere Methode"}, {"text": "Cloud-Speicher", "correct": false, "because": "Späterer Fortschritt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Hauptvorteil aktueller Trends wie KI in der Computertechnik?', 2, '[{"text": "Automatisierung", "correct": true, "because": "Erhöht Effizienz"}, {"text": "Geringere Kosten", "correct": false, "because": "Nicht primär"}, {"text": "Kleinere Größe", "correct": false, "because": "Sekundär"}]'),
-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Meilensteine prägen die Entwicklungsgeschichte der Computertechnik?', 4, '[{"text": "Erfindung des Transistors", "correct": true, "because": "Grundlage moderner Computer"}, {"text": "Einführung des Mikroprozessors", "correct": true, "because": "Start der PC-Ära"}, {"text": "Entwicklung des Internets", "correct": true, "because": "Vernetzung ermöglicht"}, {"text": "Papierherstellung", "correct": false, "because": "Unabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Trends beeinflussen aktuelle IT-Arbeitsplätze?', 3, '[{"text": "Cloud Computing", "correct": true, "because": "Flexibles Arbeiten"}, {"text": "Künstliche Intelligenz", "correct": true, "because": "Automatisierung"}, {"text": "Internet der Dinge (IoT)", "correct": true, "because": "Vernetzung"}, {"text": "Manuelle Eingabe", "correct": false, "because": "Veraltet"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Auswirkungen hatte die Computertechnik auf Arbeitsplätze?', 3, '[{"text": "Effizienzsteigerung", "correct": true, "because": "Schnellere Prozesse"}, {"text": "Automatisierung", "correct": true, "because": "Weniger manuelle Arbeit"}, {"text": "Neue Berufsfelder", "correct": true, "because": "IT-Jobs entstanden"}, {"text": "Geringere Produktivität", "correct": false, "because": "Falsch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Technologien waren historisch bedeutend?', 4, '[{"text": "Vakuumröhren", "correct": true, "because": "Erste Computer"}, {"text": "Transistoren", "correct": true, "because": "Kleinere Geräte"}, {"text": "Mikroprozessoren", "correct": true, "because": "PC-Entwicklung"}, {"text": "Papierstreifen", "correct": false, "because": "Eingeschränkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bringen aktuelle Trends in der Computertechnik?', 3, '[{"text": "Höhere Leistung", "correct": true, "because": "Schnellere Verarbeitung"}, {"text": "Flexibilität", "correct": true, "because": "Cloud und IoT"}, {"text": "Effizienz", "correct": true, "because": "Automatisierung"}, {"text": "Geringere Größe", "correct": false, "because": "Sekundär"}]'),
-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Der Mikroprozessor führte zur PC-Ära. b) Erste Computer waren für den Privatgebrauch gedacht.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Mikroprozessor ja, Privat nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Cloud Computing ist ein aktueller Trend. b) Miniaturisierung ist veraltet.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Cloud ja, Miniaturisierung aktuell"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Das Internet revolutionierte die Computertechnik. b) Trends haben keinen Einfluss auf IT-Arbeitsplätze.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Internet ja, Trends wirken"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Transistoren ersetzten Vakuumröhren. b) ENIAC war ein mechanischer Rechner.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Transistoren ja, ENIAC elektronisch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) KI automatisiert Aufgaben an IT-Arbeitsplätzen. b) Die Entwicklung der Computertechnik hat die Produktivität gesenkt.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "KI ja, Produktivität gestiegen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

